css:
.list{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.list>*:nth-child(-n+2) h3{font-size:20px}
.list>*:nth-child(n+3){grid-column:1/-1;display:grid;
  grid-template-columns:150px 1fr;gap:16px;
  border-top:1px solid #ececec;padding-top:16px}
.list>*:nth-child(n+3) h3{font-size:14px}
.list>*:nth-child(n+3) p{display:none}

/* 1件主役型 */
.grid{display:grid;grid-template-columns:1.15fr 1fr 1fr;gap:12px}
.grid>*:first-child{grid-row:span 2}
.grid>*:first-child h3{font-size:22px}
